#!/usr/bin/env python3
"""Download every page of GET /orders into PAGES_DIR, one JSON file per page.

A page is requested again until the server returns a valid answer for it:
  - 401/403: fetch a new token and retry the same page.
  - 429 or any response carrying a wait hint: sleep for the stated time, then retry.
  - 5xx, connection errors, non-JSON or malformed bodies: back off and retry.
Only accepted responses are written to disk, so each page is counted once.
"""
import email.utils
import http.client
import json
import os
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
DATA_DIR = "/tmp/recon/data"
PAGES_DIR = os.path.join(DATA_DIR, "pages")
EVENT_LOG = os.path.join(DATA_DIR, "events.log")
MAX_ATTEMPTS = 40
MAX_BACKOFF = 16.0
WAIT_MARGIN = 0.25


def log(msg):
    line = time.strftime("%H:%M:%S") + " " + msg
    print(line, flush=True)
    with open(EVENT_LOG, "a", encoding="utf-8") as f:
        f.write(line + "\n")


def send(method, path, token=None):
    headers = {"Accept": "application/json"}
    if token:
        headers["Authorization"] = "Bearer " + token
    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    if method == "POST":
        req.data = b""
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.headers, resp.read()
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read()


def header(headers, name):
    for k, v in headers.items():
        if k.lower() == name.lower():
            return v
    return None


def server_wait(headers, body):
    """Seconds the server asked us to wait, or None when it gave no hint."""
    ra = header(headers, "Retry-After")
    if ra is not None:
        try:
            return float(ra)
        except ValueError:
            try:
                when = email.utils.parsedate_to_datetime(ra)
                return max(0.0, when.timestamp() - time.time())
            except (TypeError, ValueError):
                pass
    try:
        j = json.loads(body)
    except ValueError:
        return None
    if isinstance(j, dict):
        for key in ("retry_after", "retry_after_seconds", "retryAfter"):
            if key in j:
                try:
                    return float(j[key])
                except (TypeError, ValueError):
                    pass
    return None


class Session:
    def __init__(self):
        self.token = None
        self.token_count = 0

    def refresh_token(self, reason):
        def check(d):
            if isinstance(d, dict) and isinstance(d.get("token"), str) and d["token"]:
                return None
            return "no token in body"

        data, _ = self.call("POST", "/token", auth=False, check=check)
        self.token = data["token"]
        self.token_count += 1
        log(f"new token #{self.token_count} ({reason})")

    def call(self, method, path, auth=True, check=None, not_found_ok=False):
        """Make a request and keep repeating it until the answer is usable.

        Returns (data, headers). For an allowed 404 returns (None, headers).
        """
        backoff = 1.0
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if auth and self.token is None:
                self.refresh_token("first token")
            try:
                status, headers, body = send(method, path, self.token if auth else None)
            except (OSError, http.client.HTTPException) as e:
                log(f"{method} {path} attempt {attempt}: transport error {e!r}; retry in {backoff:.1f}s")
                time.sleep(backoff)
                backoff = min(backoff * 2, MAX_BACKOFF)
                continue

            if status == 200:
                try:
                    data = json.loads(body)
                except ValueError:
                    data = None
                problem = "body is not JSON" if data is None else (check(data) if check else None)
                if problem is None:
                    return data, headers
                log(f"{method} {path} attempt {attempt}: 200 rejected ({problem}): {body[:200]!r}")
            elif status == 404 and not_found_ok:
                return None, headers
            elif status in (401, 403) and auth:
                log(f"{method} {path} attempt {attempt}: HTTP {status} {body[:200]!r}")
                self.refresh_token(f"HTTP {status} on {path}")
                continue
            else:
                log(f"{method} {path} attempt {attempt}: HTTP {status} body={body[:200]!r}")

            hint = server_wait(headers, body)
            if hint is not None:
                wait = hint + WAIT_MARGIN
                log(f"  server asked for {hint}s; waiting {wait:.2f}s")
                time.sleep(wait)
            else:
                log(f"  no wait hint; backing off {backoff:.1f}s")
                time.sleep(backoff)
                backoff = min(backoff * 2, MAX_BACKOFF)
        raise RuntimeError(f"{method} {path}: gave up after {MAX_ATTEMPTS} attempts")


def check_orders_page(page_no):
    def check(d):
        if not isinstance(d, dict):
            return "body is not an object"
        if d.get("page") != page_no:
            return f"page field is {d.get('page')!r}, expected {page_no}"
        if not isinstance(d.get("items"), list):
            return "items is not a list"
        total = d.get("total_pages")
        if not isinstance(total, int) or total < 1:
            return f"bad total_pages {total!r}"
        return None

    return check


def main():
    os.makedirs(PAGES_DIR, exist_ok=True)
    session = Session()
    page = 1
    total_seen = set()
    while True:
        data, headers = session.call(
            "GET", f"/orders?page={page}", check=check_orders_page(page)
        )
        total_seen.add(data["total_pages"])
        record = {
            "page": page,
            "headers": dict(headers.items()),
            "body": data,
        }
        out = os.path.join(PAGES_DIR, f"page-{page:03d}.json")
        with open(out, "w", encoding="utf-8") as f:
            json.dump(record, f)
        nxt = data["next"]
        log(
            f"page {page}/{data['total_pages']}: {len(data['items'])} items, next={nxt!r}"
        )
        if nxt is None:
            break
        expected = f"/orders?page={page + 1}"
        if nxt != expected:
            log(f"  WARNING: next={nxt!r} differs from expected {expected!r}; following it as given")
        page += 1
        if page > 1000:
            raise RuntimeError("runaway pagination")

    log(f"done: {page} pages fetched; total_pages values seen: {sorted(total_seen)}; tokens used: {session.token_count}")


if __name__ == "__main__":
    main()

